INSERT INTO `content_profile` VALUES ('CP1752051027317',' ','首頁文案維護',' ',' ',' ','<p style=\"text-align: center;\">麥易購，不只是團購平台，<br>而是人人可參與的智慧新經濟系統。</p>',' ',' ',' ',' ',' ',' ',' ',' ',0,' ',' ','tw','index_about',' ',' ',' ',' ',' ',' ',' ',' ','2025/07/09 16:50:27','root','2025/08/06 08:55:40','admin'),('CP1752051287591',' ','里程碑','Milestone',' ',' ','<p><img title=\"img/file\" src=\"https://www.maiyigo.com.tw/uploads/root/麥易購網站-11.png\" alt=\"\" width=\"3022\" height=\"8744\"></p>',' ',' ',' ',' ',' ',' ',' ',' ',5,' ',' ','tw','about','麥易購團購網 - 關於麥易購','index , follow','7','麥易購股份有限公司','麥易購股份有限公司','麥易購股份有限公司','<!-- Google tag (gtag.js) -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-VSELZ4BKVQ\"></script>\r\n<script>\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag(\'js\', new Date());\r\n\r\n  gtag(\'config\', \'G-VSELZ4BKVQ\');\r\n</script>','','2025/07/09 16:54:47','root','2026/06/04 17:12:51','admin'),('CP1753682205800',' ','核心價值','Core values',' ',' ','<p><img title=\"img/file\" src=\"https://www.maiyigo.com.tw/uploads/root/核心價值.jpg\" alt=\"\" width=\"2315\" height=\"5323\"></p>',' ',' ',' ',' ',' ',' ',' ',' ',4,' ',' ','tw','about','麥易購團購網','index , follow','7','麥易購股份有限公司','麥易購股份有限公司','麥易購股份有限公司','<!-- Google tag (gtag.js) -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-VSELZ4BKVQ\"></script>\r\n<script>\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag(\'js\', new Date());\r\n\r\n  gtag(\'config\', \'G-VSELZ4BKVQ\');\r\n</script>','','2025/07/28 13:56:45','admin','2026/06/04 17:12:50','admin'),('CP1752051673016',' ','打造智慧團購新經濟',' ',' ',' ','<p><span style=\"color: #34495e;\">整合 AI 工具、供應鏈、社群力量，重構團購模式，讓任何人都能經營團購事業，團購不再靠人情，而是靠系統與科技</span><br><span style=\"color: #34495e;\">讓團購變得可複製、可追蹤、可擴張</span></p>','02-07.png',' ',' ',' ',' ',' ',' ',' ',0,' ',' ','tw','service','','','','','','',' ',' ','2025/07/09 17:01:13','root','2025/11/06 16:01:18','admin'),('CP1752051786177',' ','建立去中心化零售聯盟',' ',' ',' ','<p><span style=\"color: #2dc26b;\">每一個門市、每一位團主，都是一個獨立而平等的「銷售據點」</span><br><span style=\"color: #2dc26b;\">不靠平台壟斷、不受大品牌擠壓</span><br><span style=\"color: #2dc26b;\">讓利回歸前線經營者，打造共贏生態</span></p>','麥易購-官網建置-08.png',' ',' ',' ',' ',' ',' ',' ',1,' ',' ','tw','service','','','','','','',' ',' ','2025/07/09 17:03:06','root','2025/11/06 16:01:55','admin'),('CP1752051823065',' ','用 AI 降低創業門檻',' ',' ',' ','<p><span style=\"color: #2dc26b;\">團購經營、行銷素材、客服系統，全部由 AI 輔助處理</span><br><span style=\"color: #2dc26b;\">從圖片生成、圖卡排程到自動報表，創業變簡單</span><br><span style=\"color: #2dc26b;\">你負責開團，我們幫你搞定其餘一切</span></p>','麥易購-官網建置-09.png',' ',' ',' ',' ',' ',' ',' ',2,' ',' ','tw','service','','','','','','','','','2025/07/09 17:03:43','root','2025/11/06 16:02:54','admin'),('CP1752051835113',' ','賦能在地經濟與小店轉型',' ',' ',' ','<p><span style=\"color: #3598db;\">幫助傳統門市、微型創業者進入新零售浪潮</span><br><span style=\"color: #3598db;\">一間早餐店也能月入額外2萬以上</span><br><span style=\"color: #3598db;\">創造「你買、我賣、都在社區內」的商業閉環</span></p>','麥易購-官網建置-10.png',' ',' ',' ',' ',' ',' ',' ',3,' ',' ','tw','service','','','','','','','','','2025/07/09 17:03:55','root','2025/11/06 16:03:09','admin'),('CP1752051847197',' ','建構平台共享紅利制度',' ',' ',' ','<p><span style=\"color: #3598db;\">團主、供應商、加盟主、推薦者都能共享經濟成果</span><br><span style=\"color: #3598db;\">鼓勵介紹、分享、擴張組織，人人都是股東思維</span><br><span style=\"color: #3598db;\">不只是銷售，更是建立自己的通路系統</span></p>','麥易購-官網建置-11.png',' ',' ',' ',' ',' ',' ',' ',4,' ',' ','tw','service','','','','','','','','','2025/07/09 17:04:07','root','2025/11/06 16:03:32','admin'),('CP1752054645949',' ','隱私權政策','Privacy Policy',' ',' ','<p>非常歡迎您光臨「麥易購股份有限公司」（以下簡稱本網站），為了讓您能夠安心的使用本網站的各項服務與資訊，特此向您說明本網站的隱私權保護政策，以保障您的權益，請您詳閱下列內容： <br>一、隱私權保護政策的適用範圍 <br>隱私權保護政策內容，包括本網站如何處理在您使用網站服務時收集到的個人識別資料。隱私權保護政策不適用於本網站以外的相關連結網站，也不適用於非本網站所委託或參與管理的人員。 <br>二、個人資料的蒐集、處理及利用方式 <br>&bull; 當您造訪本網站或使用本網站所提供之功能服務時，我們將視該服務功能性質，請您提供必要的個人資料，並在該特定目的範圍內處理及利用您的個人資料；非經您書面同意，本網站不會將個人資料用於其他用途。 <br>&bull; 本網站在您使用服務信箱、問卷調查等互動性功能時，會保留您所提供的姓名、電子郵件地址、聯絡方式及使用時間等。 <br>&bull; 於一般瀏覽時，伺服器會自行記錄相關行徑，包括您使用連線設備的 IP 位址、使用時間、使用的瀏覽器、瀏覽及點選資料記錄等，做為我們增進網站服務的參考依據，此記錄為內部應用，決不對外公佈。 <br>&bull; 為提供精確的服務，我們會將收集的問卷調查內容進行統計與分析，分析結果之統計數據或說明文字呈現，除供內部研究外，我們會視需要公佈統計數據及說明文字，但不涉及特定個人之資料。 <br>&bull; 您可以隨時向我們提出請求，以更正或刪除本網站所蒐集您錯誤或不完整的個人資料。 <br>三、資料之保護 <br>&bull; 本網站主機均設有防火牆、防毒系統等相關的各項資訊安全設備及必要的安全防護措施，加以保護網站及您的個人資料採用嚴格的保護措施，只由經過授權的人員才能接觸您的個人資料，相關處理人員皆簽有保密合約，如有違反保密義務者，將會受到相關的法律處分。 <br>&bull; 如因業務需要有必要委託其他單位提供服務時，本網站亦會嚴格要求其遵守保密義務，並且採取必要檢查程序以確定其將確實遵守。 <br>四、網站對外的相關連結 <br>本網站的網頁提供其他網站的網路連結，您也可經由本網站所提供的連結，點選進入其他網站。但該連結網站不適用本網站的隱私權保護政策，您必須參考該連結網站中的隱私權保護政策。 <br>五、與第三人共用個人資料之政策 <br>本網站絕不會提供、交換、出租或出售任何您的個人資料給其他個人、團體、私人企業或公務機關，但有法律依據或合約義務者，不在此限。 <br>前項但書之情形包括不限於： <br>&bull; 經由您書面同意。 <br>&bull; 法律明文規定。 <br>&bull; 為免除您生命、身體、自由或財產上之危險。 <br>&bull; 與公務機關或學術研究機構合作，基於公共利益為統計或學術研究而有必要，且資料經過提供者處理或蒐集者依其揭露方式無從識別特定之當事人。 <br>&bull; 當您在網站的行為，違反服務條款或可能損害或妨礙網站與其他使用者權益或導致任何人遭受損害時，經網站管理單位研析揭露您的個人資料是為了辨識、聯絡或採取法律行動所必要者。 <br>&bull; 有利於您的權益。 <br>&bull; 本網站委託廠商協助蒐集、處理或利用您的個人資料時，將對委外廠商或個人善盡監督管理之責。 <br>六、Cookie 之使用 <br>為了提供您最佳的服務，本網站會在您的電腦中放置並取用我們的 Cookie，若您不願接受 Cookie 的寫入，您可在您使用的瀏覽器功能項中設定隱私權等級為高，即可拒絕 Cookie 的寫入，但可能會導致網站某些功能無法正常執行 。 <br>七、隱私權保護政策之修正 <br>本網站隱私權保護政策將因應需求隨時進行修正，修正後的條款將刊登於網站上。</p>',' ',' ',' ',' ',' ',' ',' ',' ',0,' ',' ','tw','notice','','index , follow','','','','','<!-- Google tag (gtag.js) -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-VSELZ4BKVQ\"></script>\r\n<script>\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag(\'js\', new Date());\r\n\r\n  gtag(\'config\', \'G-VSELZ4BKVQ\');\r\n</script>','','2025/07/09 17:50:45','root','2026/03/11 16:58:42','admin'),('CP1752054663906',' ','退款政策','Refund Policy',' ',' ','<p>非常歡迎您光臨「麥易購股份有限公司」（以下簡稱本網站），為了讓您能夠安心的使用本網站的各項服務與資訊，特此向您說明本網站的隱私權保護政策，以保障您的權益，請您詳閱下列內容： <br>一、隱私權保護政策的適用範圍 <br>隱私權保護政策內容，包括本網站如何處理在您使用網站服務時收集到的個人識別資料。隱私權保護政策不適用於本網站以外的相關連結網站，也不適用於非本網站所委託或參與管理的人員。 <br>二、個人資料的蒐集、處理及利用方式 <br>&bull; 當您造訪本網站或使用本網站所提供之功能服務時，我們將視該服務功能性質，請您提供必要的個人資料，並在該特定目的範圍內處理及利用您的個人資料；非經您書面同意，本網站不會將個人資料用於其他用途。 <br>&bull; 本網站在您使用服務信箱、問卷調查等互動性功能時，會保留您所提供的姓名、電子郵件地址、聯絡方式及使用時間等。 <br>&bull; 於一般瀏覽時，伺服器會自行記錄相關行徑，包括您使用連線設備的 IP 位址、使用時間、使用的瀏覽器、瀏覽及點選資料記錄等，做為我們增進網站服務的參考依據，此記錄為內部應用，決不對外公佈。 <br>&bull; 為提供精確的服務，我們會將收集的問卷調查內容進行統計與分析，分析結果之統計數據或說明文字呈現，除供內部研究外，我們會視需要公佈統計數據及說明文字，但不涉及特定個人之資料。 <br>&bull; 您可以隨時向我們提出請求，以更正或刪除本網站所蒐集您錯誤或不完整的個人資料。 <br>三、資料之保護 <br>&bull; 本網站主機均設有防火牆、防毒系統等相關的各項資訊安全設備及必要的安全防護措施，加以保護網站及您的個人資料採用嚴格的保護措施，只由經過授權的人員才能接觸您的個人資料，相關處理人員皆簽有保密合約，如有違反保密義務者，將會受到相關的法律處分。 <br>&bull; 如因業務需要有必要委託其他單位提供服務時，本網站亦會嚴格要求其遵守保密義務，並且採取必要檢查程序以確定其將確實遵守。 <br>四、網站對外的相關連結 <br>本網站的網頁提供其他網站的網路連結，您也可經由本網站所提供的連結，點選進入其他網站。但該連結網站不適用本網站的隱私權保護政策，您必須參考該連結網站中的隱私權保護政策。 <br>五、與第三人共用個人資料之政策 <br>本網站絕不會提供、交換、出租或出售任何您的個人資料給其他個人、團體、私人企業或公務機關，但有法律依據或合約義務者，不在此限。 <br>前項但書之情形包括不限於： <br>&bull; 經由您書面同意。 <br>&bull; 法律明文規定。 <br>&bull; 為免除您生命、身體、自由或財產上之危險。 <br>&bull; 與公務機關或學術研究機構合作，基於公共利益為統計或學術研究而有必要，且資料經過提供者處理或蒐集者依其揭露方式無從識別特定之當事人。 <br>&bull; 當您在網站的行為，違反服務條款或可能損害或妨礙網站與其他使用者權益或導致任何人遭受損害時，經網站管理單位研析揭露您的個人資料是為了辨識、聯絡或採取法律行動所必要者。 <br>&bull; 有利於您的權益。 <br>&bull; 本網站委託廠商協助蒐集、處理或利用您的個人資料時，將對委外廠商或個人善盡監督管理之責。 <br>六、Cookie 之使用 <br>為了提供您最佳的服務，本網站會在您的電腦中放置並取用我們的 Cookie，若您不願接受 Cookie 的寫入，您可在您使用的瀏覽器功能項中設定隱私權等級為高，即可拒絕 Cookie 的寫入，但可能會導致網站某些功能無法正常執行 。 <br>七、隱私權保護政策之修正 <br>本網站隱私權保護政策將因應需求隨時進行修正，修正後的條款將刊登於網站上。</p>',' ',' ',' ',' ',' ',' ',' ',' ',1,' ',' ','tw','notice','','index , follow','','','','','<!-- Google tag (gtag.js) -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-VSELZ4BKVQ\"></script>\r\n<script>\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag(\'js\', new Date());\r\n\r\n  gtag(\'config\', \'G-VSELZ4BKVQ\');\r\n</script>','','2025/07/09 17:51:03','root','2026/03/11 16:58:54','admin'),('CP1752054679273',' ','使用條款','Terms of Use',' ',' ','<div>非常歡迎您光臨「麥易購網站」（以下簡稱本網站），為了讓您能夠安心的使用本網站的各項服務與資訊，特此向您說明本網站的會員聲明，以保障您的權益，請您詳閱下列內容：</div>\r\n<div>&nbsp;</div>\r\n<div>一、會員服務條款</div>\r\n<div>1.本會員服務條款所稱之「會員」，為依照本站所定之加入會員程序加入完成並通過認證者。</div>\r\n<div>2.當您使用本站服務時，即表示您同意及遵守本服務條款的規定事項及相關法律之規定。</div>\r\n<div>3.本站保留有審核加入會員資格之權利，另外已加入會員者，本站亦保留有解除其會員資格之權利。</div>\r\n<div>4.本會員服務條款之修訂，適用於所有會員，當本站修訂本服務條款時，將於本站上公告。</div>\r\n<div>&nbsp;</div>\r\n<div>二、隱私權保護</div>\r\n<div>尊重並依據本網站「隱私權保護聲明」保護您的隱私(請參閱「隱私權保護聲明」條款)。</div>\r\n<div>&nbsp;</div>\r\n<div>三、會員</div>\r\n<div>1.使用本站所提供之會員服務時，於加入會員時所登錄之帳號及密碼使用之。</div>\r\n<div>2.會員須善盡帳號及密碼的使用與管理之責任。對於使用該會員之帳號及密碼(無關於會員本身或其他人)利用本站服務所造成或衍生之所有行為及結果，會員須自行負擔全部責任。</div>\r\n<div>3.會員之帳號及密碼遺失，或發現無故遭第三者盜用時，應立即通知本站連絡掛失，因未即時通知，導致本站無法有效防止及修改時，所造成的所有損失，會員應自負全責。</div>\r\n<div>4.每次結束使用本服務，執行會員之登出並關閉視窗，以確保您的會員權益。</div>\r\n<div>5.盜用第三者會員之帳號及密碼，導致第三者或本公司遭其他第三人或行政機關之調查或追訴時，第三者會員或本公司有權向您請求損害賠償，包括但不限於訴訟費用、律師費及商譽損失等。</div>\r\n<div>&nbsp;</div>\r\n<div>四、會員登錄資料</div>\r\n<div>1.會員登錄資料須提供您本人正確、最新及完整的資料。</div>\r\n<div>2.會員登錄資料不得有偽造、不實等之情事(ex如個人資料及信用卡資料)，一經發現本公司可拒絕其加入會員資格之權利。並得以暫停或終止其會員資格，若違反中華民國相關法律，亦將依法追究。</div>\r\n<div>3.會員基本資料(ex:住址，電話及其他登錄資料)有變更時，請不定期更新相關個人資料，確保其正確及完整性。若您提供的資料有錯誤或不符等現象，本網站有權暫停或終止您的帳號，並拒絕您繼續使用本服務。</div>\r\n<div>4.未經會員本人同意，本公司原則上不會將涉及個人隱私之資料開示給第三者，唯資料共用原則&hellip;等不在此限(請參閱本站「隱私權保護聲明」相關規定)。</div>\r\n<div>5.會員應妥善保管密碼，不可將密碼洩露或提供給他人知道或使用；以同一個會員身分證字號和密碼使用本服務所進行的所有行為，都將被認為是該會員本人和密碼持有人的行為。</div>\r\n<div>6.會員如果發現或懷疑有第三人使用其會員身分證字號或密碼，應該立即通知本公司，採取必要的必要的防範措施。但上述通知不得解釋為本公司對會員負有任何形式之賠償或補償之責任或義務。</div>\r\n<div>&nbsp;</div>\r\n<div>五、使用行為</div>\r\n<div>1.您使用本服務之一切行為必須符合當地或國際相關法令規範；對於使用者的一切行為，您須自行負擔全部責任。</div>\r\n<div>2.您同意絕不為非法之目的或以非法方式使用本服務，與確實遵守中華民國相關法規及網際網路之國際慣例，並保證不得利用本服務從事侵害他人權益或違法之行為。</div>\r\n<div>3.您於使用本站會員服務時應遵守以下限制：</div>\r\n<div>&nbsp;</div>\r\n<div>有損他人人格或商標權、著作權等智慧財產權或其他權利內容。</div>\r\n<div>使用違反公共秩序或善良風俗或其他不法之文字。</div>\r\n<div>強烈政治、宗教色彩的偏激言論。</div>\r\n<div>未經本公司許可，不得利用本服務或本網站所提供其他資源，包括但不限於圖文資料庫、編寫製作網頁之軟體等，從事任何商業交易行為，或招攬廣告商或贊助人。</div>\r\n<div>其他違反本站「會員服務條款」的內容。</div>\r\n<div>六、本公司專有權利</div>\r\n<div>1.本服務所載，或本服務所連結之一切軟體或內容，或本公司之廣告商或合夥人所提供之內容，均受其著作權或其他專有權利或法律所保障。</div>\r\n<div>2.當您傳輸資料至本公司提供之服務時，您即同意此一資料為全開放性(任何人均可瀏覽)。您授權並許可本公司得以重製、修飾、改編或以其他形式使用該內容之全部或一部分，及利用該內容製作衍生著作。衍生著作之著作權悉歸本公司所有。</div>\r\n<div>&nbsp;</div>\r\n<div>3.本公司同意除依本使用條款約定，將前述您的資料及衍生著作置於本網站供網路使用者瀏覽，以及本公司所屬相關媒體外，絕不非法轉供其他直接營利目的或侵害您的權利之使用。</div>\r\n<div>&nbsp;</div>\r\n<div>4.所有網頁之頁面出現之廣告看板與活動訊息，所有權及經營權均為本公司所有，使用者除事先取得本公司同意外，不得自行使用所有訊息。</div>\r\n<div>5.會員同意並授權本網站，得為提供個人化服務或相關加值服務之目的，提供所需之會員資料給合作單位(第三者)做約定範圍內之運用，如會員不同意將其資料列於合作單位(第三者)產品或服務名單內，可通知本網站於名單中刪除其資料，並同時放棄其本網站以外之購物優惠或獲獎權利。</div>\r\n<div>6.同時為提供行銷、市場分析、統計或研究、或為提供會員個人化服務或加值服務之目的，會員同意本公司、或本公司之策略合作夥伴，得記錄、保存、並利用會員在本網站所留存或產生之資料及記錄，同時在不揭露各該資料之情形下得公開或使用統計資料。</div>\r\n<div>7.對於會員所登錄之個人資料，會員同意本網站得於合理之範圍內蒐集、處理、保存、傳遞及使用該等資料，以提供使用者其他資訊或服務、或作成會員統計資料、或進行關於網路行為之調查或行銷研究。</div>\r\n<div>&nbsp;</div>\r\n<div>七、終止授權</div>\r\n<div>您使用本服務之行為若有任何違反法令或本使用條款或危害本網站或第三者權益之虞時，本公司有權不經告知您，立即暫時或永久終止您使用本服務之授權。</div>\r\n<div>&nbsp;</div>\r\n<div>八、免責事項</div>\r\n<div>1.下列情形發生時，本網站有權可以停止、中斷提供本服務：</div>\r\n<div>&nbsp;</div>\r\n<div>對本服務相關軟硬體設備進行更換、升級、保養或施工時。</div>\r\n<div>發生突發性之電子通信設備故障時。</div>\r\n<div>天災或其他不可抗力之因素致使本網站無法提供服務時。</div>\r\n<div>2.本公司對於使用者在使用本服務或使用本服務所致生之任何直接、間接、衍生之財產或非財產之損害，不負賠償責任。</div>\r\n<div>3.使用者對於上傳留言之文字、圖片及其它資料，應自行備份；本公司對於任何原因導致其內容全部或一部之滅失、毀損，不負任何責任。</div>\r\n<div>4.本公司對使用本服務之用途或所產生的結果，不負任何保證責任，亦不保證與本服務相關之軟體無缺失或會予以修正。</div>\r\n<div>5.對於您在本站中的所有言論、意見或行為僅代表您個人；不代表本公司的立場，本公司不負任何責任。本公司對於使用者所自稱之身分，不擔保其正確性。</div>\r\n<div>6.本公司無須對發生於本服務或透過本服務所涉及之任何恐嚇、誹謗、淫穢或其他一切不法行為對您或任何人負責。</div>\r\n<div>7.對於您透過本服務所購買或取得，或透過本公司之贊助者或廣告商所刊登、銷售或交付之任何貨品或服務，您應自行承擔其可能風險或依法向商品或服務提供者交涉求償，與本公司完全無關，本公司均不負任何責任。</div>\r\n<div>&nbsp;</div>\r\n<div>九、修改權</div>\r\n<div>1.當您開始使用本服務時，即表示您已充分閱讀、瞭解與同意接受本條款之內容。本公司有權於任何時間修改與變更本條款之內容，並將不個別通知會員，建議您定期查閱本服務條款。如您於本條款修改與變更後仍繼續使用本服務，則視為您已閱讀、瞭解與同意接受本條款修改或變更。</div>\r\n<div>2.本公司有權暫時或永久修改或中止提供本服務給您，您不得因此要求任何賠償。</div>\r\n<div>&nbsp;</div>\r\n<div>十、智慧財產權的保護</div>\r\n<div>1.本網站所使用之軟體、程式及網站上所有內容，包括但不限於著作、圖片、檔案、資訊、資料、網站架構、網頁設計，均由本網站或其他權利人依法擁有其智慧財產權，包括但不限於商標權、專利權、著作權、營業秘密與專有技術等。</div>\r\n<div>2.任何人不得逕行使用、修改、重製、公開播送、改作、散布、發行、公開發表、進行還原工程、解編或反向組譯。如欲引用或轉載前述之軟體、程式或網站內容，必須依法取得本網站或其他權利人的事前書面同意。如有違反之情事，您應對本網站或其他權利人負損害賠償責任（包括但不限於訴訟費用及律師費用等）。</div>\r\n<div>&nbsp;</div>\r\n<div>十一、其他規定</div>\r\n<div>1.本網站使用者條約，免責之內容，亦構成本使用條款之一部分。</div>\r\n<div>2.凡因使用本服務所生之爭執，均以台灣臺中地方法院為第一審管轄法院。</div>\r\n<div>3.若因您使用本服務之任何行為，導致本公司遭第三人或行政機關之調查或追訴時，本公司有權向您請求損害賠償，包括但不限於訴訟費用、律師費及商譽損失等。</div>\r\n<div>4.本公司針對可預知之軟硬體維護工作，有可能導致系統中斷或是暫停者，將會於該狀況發生前，以適當之方式告知會員。</div>\r\n<div>&nbsp;</div>\r\n<div>十二、會員身份終止與本公司通知之義務：</div>\r\n<div>1.本公司具有更改各項服務內容或終止任一會員帳戶服務之權利。</div>\r\n<div>2.若會員決定終止本公司會員資格，可直接以電子郵件的方式通知本公司或是由本公司所提供之機制進行取消，本公司將儘快註銷您的會員資料。</div>\r\n<div>3.會員有通知取消本公司會員資格之義務，並自停止本公司會員身份之日起（以本公司電子郵件發出日期為準），喪失所有本服務所提供之優惠及權益。</div>\r\n<div>4.為避免惡意情事發生致使會員應享權益損失，當會員通知本公司停止會員身份時，本公司將再次以電子郵件確認無誤後，再進行註銷會員資格。</div>',' ',' ',' ',' ',' ',' ',' ',' ',2,' ',' ','tw','notice','','index , follow','','','','','<!-- Google tag (gtag.js) -->\r\n<script async src=\"https://www.googletagmanager.com/gtag/js?id=G-VSELZ4BKVQ\"></script>\r\n<script>\r\n  window.dataLayer = window.dataLayer || [];\r\n  function gtag(){dataLayer.push(arguments);}\r\n  gtag(\'js\', new Date());\r\n\r\n  gtag(\'config\', \'G-VSELZ4BKVQ\');\r\n</script>','','2025/07/09 17:51:19','root','2026/03/11 16:59:06','admin'),('CP1752114505320',' ','聯絡資訊維護','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d14515.399831033536!2d120.8137290218609!3d24.55984659061096!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3469abf86c808cd5%3A0x598154a01996d822!2zMzYw6IuX5qCX57ij6IuX5qCX5biC5ZyL6I-v6LevMTIzN-iZnzE!5e0!3m2!1szh-TW!2stw!4v1752025974914!5m2!1szh-TW!2stw',' ',' ','<p>&nbsp;</p>\r\n<p><img style=\"display: block; margin-left: auto; margin-right: auto;\" title=\"img/file\" src=\"https://www.maiyigo.com.tw/uploads/root/麥易購網站-03-1.png\" alt=\"\" width=\"1240\" height=\"550\"></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: center;\"><span style=\"font-size: 50px;\"><span style=\"color: #3598db;\"><span style=\"font-size: 50px;\"><img style=\"display: block; margin-left: auto; margin-right: aut